local function same(a,b)
  if type(a)~=type(b) then return false end
  if type(a)~="table" then return a==b end
  for k,v in pairs(a) do if not same(v,b[k]) then return false end end
  for k in pairs(b) do if a[k]==nil then return false end end
  return true
end
local function copy(t)
  if type(t)~="table" then return t end
  local result={}
  for k,v in pairs(t) do result[k]=copy(v) end
  return result
end
local applied,skipped=0,0
local quests=pfDB and pfDB.quests and pfDB.quests["data-turtle"]
if quests then
  for _,fix in ipairs(fixes) do
    local quest=quests[fix.id]
    -- Existing objectives, deleted records and unexpected metadata are left intact.
    if type(quest)=="table" and quest.obj==nil and same(quest,fix.expected) then
      quest.obj=copy(fix.objectives)
      applied=applied+1
    else
      skipped=skipped+1
    end
  end
end
pfQuestTurtleObjectiveFixes={version="1.0.1",candidateCount=685,applied=applied,skipped=skipped}
